CREATE TABLE artifact_object_ingestions (
 id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY, tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, object_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 created_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, creation_key CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, fingerprint VARBINARY(32) NOT NULL CHECK(OCTET_LENGTH(fingerprint)=32),
 kind VARCHAR(16) NOT NULL CHECK(kind IN('model','dataset')), model_import_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin, dataset_draft_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin, target_dataset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 state VARCHAR(16) NOT NULL CHECK(state IN('intent','running','submitted','failed')),
 source_verified_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin, source_verified_at DATETIME(6),
 input JSON NOT NULL CHECK(JSON_TYPE(input)='OBJECT' AND OCTET_LENGTH(CAST(input AS CHAR CHARACTER SET utf8mb4))<=16384),
 receipt JSON CHECK(receipt IS NULL OR JSON_TYPE(receipt)='OBJECT' AND OCTET_LENGTH(CAST(receipt AS CHAR CHARACTER SET utf8mb4))<=16384),
 error_code VARCHAR(64), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 UNIQUE(tenant_id,workspace_id,object_id,created_by,creation_key),
 FOREIGN KEY(tenant_id,workspace_id,object_id) REFERENCES artifact_objects(tenant_id,workspace_id,id), FOREIGN KEY(created_by) REFERENCES users(id),
 FOREIGN KEY(tenant_id,workspace_id,target_dataset_id) REFERENCES datasets(tenant_id,workspace_id,id),
 FOREIGN KEY(tenant_id,workspace_id,model_import_id) REFERENCES model_imports(tenant_id,workspace_id,id),
 FOREIGN KEY(tenant_id,workspace_id,target_dataset_id,dataset_draft_id) REFERENCES dataset_drafts(tenant_id,workspace_id,dataset_id,id),
 CHECK((kind='model' AND dataset_draft_id IS NULL AND target_dataset_id IS NULL) OR (kind='dataset' AND model_import_id IS NULL AND target_dataset_id IS NOT NULL)),
 CHECK(state<>'submitted' OR (kind='model' AND model_import_id IS NOT NULL) OR (kind='dataset' AND dataset_draft_id IS NOT NULL)),
 CONSTRAINT aingest_id CHECK(REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aingest_tenant_id CHECK(REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aingest_workspace_id CHECK(REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aingest_object_id CHECK(REGEXP_LIKE(object_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aingest_created_by CHECK(REGEXP_LIKE(created_by,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aingest_creation_key CHECK(REGEXP_LIKE(creation_key,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aingest_model_import_id CHECK(model_import_id IS NULL OR REGEXP_LIKE(model_import_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aingest_dataset_draft_id CHECK(dataset_draft_id IS NULL OR REGEXP_LIKE(dataset_draft_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
 CONSTRAINT aingest_target_dataset_id CHECK(target_dataset_id IS NULL OR REGEXP_LIKE(target_dataset_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;